<?php
declare(strict_types=1);
namespace CommunityHub;
final class Members {
 const HEADS=['department_command','admin','management','owner'];
 public static function documents(string $method,string $path,array $d):void{$u=Auth::requireUser(true);if(preg_match('~^/documents/(\d+)/(download|remove|restore)$~',$path,$m)){$id=(int)$m[1];if($m[2]==='download'){$r=App::row('SELECT d.*,c.file_data FROM documents d LEFT JOIN document_contents c ON c.document_id=d.id WHERE d.id=? AND d.deleted_at IS NULL',[$id]);if(!$r)throw new HttpError('Document unavailable.',404);$bytes=$r['file_data'];if($bytes===null){$name=$r['stored_name'];if(basename($name)!==$name)throw new HttpError('Invalid stored document path.',404);$file=App::env('UPLOAD_DIR',dirname(__DIR__).'/storage/uploads').'/'.$name;if(!is_file($file))throw new HttpError('This legacy file is missing. Restore its backup.',404);$bytes=file_get_contents($file);}header('Content-Type: '.$r['mime_type']);header('Content-Disposition: attachment; filename="'.str_replace(["\r","\n",'"','\\'],'',$r['original_name']).'"; filename*=UTF-8\'\''.rawurlencode($r['original_name']));echo $bytes;return;}if($method!=='POST')throw new HttpError('Method not allowed.',405);Domain::role($u,Domain::ADMINS);$q=$m[2]==='remove'?App::query('UPDATE documents SET deleted_at=NOW(),deleted_by=? WHERE id=? AND deleted_at IS NULL',[$u['id'],$id]):App::query('UPDATE documents SET deleted_at=NULL,deleted_by=NULL WHERE id=? AND deleted_at IS NOT NULL',[$id]);if(!$q->rowCount())throw new HttpError('Document unavailable.',404);App::redirect('/documents');}if($path==='/documents/upload'&&$method==='POST'){Domain::role($u,Domain::STAFF);$f=$_FILES['document']??null;if(!$f||$f['error']!==UPLOAD_ERR_OK||!is_uploaded_file($f['tmp_name']))throw new HttpError('Select a document to upload.');$max=(int)App::env('MAX_UPLOAD_MB','25')*1048576;if($f['size']>$max)throw new HttpError('Document exceeds the upload limit.',413);$packet=App::row('SELECT @@max_allowed_packet packet_size');if($f['size']+4096>(int)$packet['packet_size'])throw new HttpError('This document exceeds the database packet limit.',413);$bytes=file_get_contents($f['tmp_name']);$mime=(new \finfo(FILEINFO_MIME_TYPE))->file($f['tmp_name'])?:'application/octet-stream';App::transaction(function()use($u,$f,$bytes,$mime,$d){$id=App::insert('INSERT INTO documents(folder_id,title,original_name,stored_name,mime_type,file_size,uploaded_by) VALUES(?,?,?,?,?,?,?)',[!empty($d['folder_id'])?App::id($d['folder_id']):null,App::text($d['title']??$f['name'],'Title',255),basename($f['name']),bin2hex(random_bytes(16)),$mime,$f['size'],$u['id']]);App::query('INSERT INTO document_contents(document_id,file_data,sha256) VALUES(?,?,?)',[$id,$bytes,hash('sha256',$bytes)]);});App::redirect('/documents');}if($path!=='/documents')throw new HttpError('Page not found.',404);View::layout('Documents',function()use($u){View::heading('Documents','Community policies, procedures and training material.');$rows=App::rows('SELECT d.id,d.title,d.original_name,d.created_at,f.name folder_name FROM documents d LEFT JOIN document_folders f ON f.id=d.folder_id WHERE d.deleted_at IS NULL ORDER BY d.created_at DESC');View::table($rows,['title'=>'Title','folder_name'=>'Folder','created_at'=>'Added'],function($r)use($u){?><a href="/documents/<?=(int)$r['id']?>/download">Download</a><?php if(in_array($u['role'],Domain::ADMINS,true))View::form('/documents/'.$r['id'].'/remove',[],'Remove');});if(in_array($u['role'],Domain::STAFF,true)):?><section class="panel"><h2>Upload document</h2><form method="post" action="/documents/upload" enctype="multipart/form-data"><?php View::csrf();?><label>Title<input name="title" maxlength="255" required></label><label>Folder<select name="folder_id"><option value="">No folder</option><?php foreach(App::rows('SELECT id,name FROM document_folders ORDER BY name') as $f):?><option value="<?=(int)$f['id']?>"><?=escape($f['name'])?></option><?php endforeach?></select></label><label>File<input type="file" name="document" required></label><button class="btn">Upload document</button></form></section><?php endif;if(in_array($u['role'],Domain::ADMINS,true)){View::heading('Removed documents');View::table(App::rows('SELECT id,title,deleted_at FROM documents WHERE deleted_at IS NOT NULL ORDER BY deleted_at DESC'),['title'=>'Title','deleted_at'=>'Removed'],fn($r)=>View::form('/documents/'.$r['id'].'/restore',[],'Restore'));}});}
 public static function calendar(string $method,string $path,array $d):void{$u=Auth::requireUser(true);if($path==='/calendar/api/events')App::json(App::rows('SELECT id,title,event_type,start_at AS start,end_at AS end,description,location FROM calendar_events WHERE start_at BETWEEN ? AND ?',[$_GET['start']??'1970-01-01',$_GET['end']??'2100-01-01']));if($path==='/calendar/admin/events'&&$method==='POST'){Domain::role($u,Domain::STAFF);$title=App::text($d['title']??null,'Title',180);if(empty($d['start_at'])||strtotime($d['start_at'])===false)throw new HttpError('Select a valid start time.');App::query('INSERT INTO calendar_events(title,event_type,start_at,end_at,description,location,department_id,max_attendees,created_by) VALUES(?,?,?,?,?,?,?,?,?)',[$title,$d['event_type']??'community',$d['start_at'],$d['end_at']?:$d['start_at'],$d['description']?:null,$d['location']?:null,!empty($d['department_id'])?App::id($d['department_id']):null,!empty($d['max_attendees'])?App::id($d['max_attendees']):null,$u['id']]);App::redirect('/calendar');}if($path!=='/calendar')throw new HttpError('Page not found.',404);View::layout('Calendar',function()use($u){View::heading('Community calendar');foreach(App::rows('SELECT * FROM calendar_events WHERE end_at>=DATE_SUB(NOW(),INTERVAL 1 DAY) ORDER BY start_at LIMIT 250') as $e){?><article class="event"><time><?=escape($e['start_at'])?></time><div><h2><?=escape($e['title'])?></h2><p><?=escape($e['location'])?></p><?php View::prose($e['description']);?></div></article><?php }if(in_array($u['role'],Domain::STAFF,true))View::form('/calendar/admin/events',['title'=>['label'=>'Title','required'=>true],'event_type'=>'Event type','start_at'=>['label'=>'Start','type'=>'datetime-local','required'=>true],'end_at'=>['label'=>'End','type'=>'datetime-local'],'description'=>['label'=>'Description','type'=>'textarea'],'location'=>'Location','department_id'=>['label'=>'Department ID','type'=>'number'],'max_attendees'=>['label'=>'Maximum attendees','type'=>'number']],'Create event');});}
 public static function learning(string $method,string $path,array $d):void{$u=Auth::requireUser(true);if(preg_match('~^/lms/courses/(\d+)/enroll$~',$path,$m)&&$method==='POST'){Learning::enroll($u,(int)$m[1]);App::redirect('/lms/courses/'.$m[1]);}if(preg_match('~^/lms/courses/(\d+)/lessons/(\d+)/(complete|assessment)$~',$path,$m)&&$method==='POST'){Learning::complete((int)$u['id'],(int)$m[1],(int)$m[2],$m[3]==='assessment'?($d['answers']??[]):null);App::redirect('/lms/courses/'.$m[1].'#lesson-'.$m[2]);}if(preg_match('~^/lms/courses/(\d+)$~',$path,$m)){$c=App::row("SELECT c.*,e.id enrollment_id,e.status enrollment_status,e.progress_percent FROM lms_courses c LEFT JOIN lms_enrollments e ON e.course_id=c.id AND e.user_id=? WHERE c.id=? AND (c.status='published' OR ?=1)",[$u['id'],(int)$m[1],(int)in_array($u['role'],Domain::STAFF,true)]);if(!$c)throw new HttpError('Course not found.',404);View::layout($c['title'],function()use($c,$u){View::heading($c['title'],$c['description']??'','TRAINING');if(!$c['enrollment_id']){View::form('/lms/courses/'.$c['id'].'/enroll',[],'Start course');return;}?><p><?=escape($c['enrollment_status'])?> · <?=escape($c['progress_percent'])?>% complete</p><?php foreach(App::rows('SELECT * FROM lms_modules WHERE course_id=? ORDER BY sort_order,id',[$c['id']]) as $module){?><section class="panel"><h2><?=escape($module['title'])?></h2><?php foreach(App::rows('SELECT l.*,p.status progress_status,p.score FROM lms_lessons l LEFT JOIN lms_lesson_progress p ON p.lesson_id=l.id AND p.enrollment_id=? WHERE l.module_id=? ORDER BY l.sort_order,l.id',[$c['enrollment_id'],$module['id']]) as $l){?><article id="lesson-<?=(int)$l['id']?>" class="lesson"><h3><?=escape($l['title'])?></h3><small><?=escape($l['progress_status']??'Not started')?><?=$l['score']!==null?' · '.escape($l['score']).'%':''?></small><?php View::prose($l['content']);if($l['resource_url']&&filter_var($l['resource_url'],FILTER_VALIDATE_URL)&&in_array(parse_url($l['resource_url'],PHP_URL_SCHEME),['http','https'],true)):?><a href="<?=escape($l['resource_url'])?>" target="_blank" rel="noopener noreferrer">Open resource</a><?php endif;if($l['lesson_type']==='quiz'){$a=Learning::assessment((int)$l['id']);?><form method="post" action="/lms/courses/<?=(int)$c['id']?>/lessons/<?=(int)$l['id']?>/assessment"><?php View::csrf();foreach($a['questions'] as $q):?><fieldset class="assessment-question"><legend><?=escape($q['question_text'])?></legend><?php foreach($a['answers'] as $answer)if($answer['question_id']==$q['id']):?><label><input type="radio" name="answers[<?=(int)$q['id']?>]" value="<?=(int)$answer['id']?>" required><?=escape($answer['answer_text'])?></label><?php endif?></fieldset><?php endforeach?><button class="btn">Submit assessment</button></form><?php }else View::form('/lms/courses/'.$c['id'].'/lessons/'.$l['id'].'/complete',[],'Mark lesson complete');?></article><?php }?></section><?php }});return;}if($path!=='/lms')throw new HttpError('Page not found.',404);$data=Domain::learning($u,true);View::layout('My training',function()use($data){View::heading('My training','Current progress, available courses and earned certifications.');?><section class="panel"><h2>Current and completed training</h2><?php View::table($data['courses'],['title'=>'Course','status'=>'Status','progress_percent'=>'Progress %','final_score'=>'Score %'],function($c){?><a href="/lms/courses/<?=(int)$c['id']?>">Continue / review</a><?php });?></section><section class="panel"><h2>Course catalog</h2><?php View::table($data['available_courses'],['title'=>'Course','estimated_minutes'=>'Minutes','passing_score'=>'Pass mark %'],function($c){?><a href="/lms/courses/<?=(int)$c['id']?>">View course</a><?php });?></section><section class="panel"><h2>Certifications</h2><?php View::table($data['certifications'],['name'=>'Certification','validity_status'=>'Status','awarded_at'=>'Awarded','expires_at'=>'Expires']);?></section><?php });}
 public static function training(string $method,string $path,array $d):void{$u=Auth::requireUser(true);if($method==='POST'){
  if(preg_match('~^/training/(\d+)/(register|cancel)$~',$path,$m)){$id=(int)$m[1];if($m[2]==='cancel'){App::query("UPDATE training_registrations SET status='cancelled' WHERE training_id=? AND user_id=?",[$id,$u['id']]);App::redirect('/training');}$type=($d['registration_type']??'')==='instructor'?'instructor':'student';if($type==='instructor')Domain::role($u,[...self::HEADS,'staff']);App::transaction(function()use($id,$u,$type){$t=App::row('SELECT * FROM training_sessions WHERE id=? AND registration_open=1 FOR UPDATE',[$id]);if(!$t)throw new HttpError('Training registration is closed.',404);$old=App::row("SELECT id,status FROM training_registrations WHERE training_id=? AND user_id=?",[$id,$u['id']]);$count=App::row("SELECT COUNT(*) count FROM training_registrations WHERE training_id=? AND registration_type=? AND status='registered' AND user_id<>?",[$id,$type,$u['id']]);if((int)$count['count']>=(int)$t[$type.'_seats'])throw new HttpError('No '.$type.' seats remain.',409);App::query("INSERT INTO training_registrations(training_id,user_id,registration_type,status,result_status) VALUES(?,?,?,'registered','pending') ON DUPLICATE KEY UPDATE registration_type=VALUES(registration_type),status='registered',result_status='pending',score=NULL,instructor_notes=NULL,completed_by=NULL,completed_at=NULL",[$id,$u['id'],$type]);Automation::emit('training_registered',['entity_type'=>'training','entity_id'=>$id,'subject_user_id'=>(int)$u['id'],'training_id'=>$id,'title'=>$t['title'],'department_id'=>$t['department_id'],'registration_type'=>$type,'status'=>'registered','start_at'=>$t['start_at']],(int)$u['id']);});App::redirect('/training');}
  Domain::role($u,self::HEADS);
  if($path==='/training/admin/create'){App::query('INSERT INTO training_sessions(department_id,title,description,location,start_at,end_at,instructor_seats,student_seats,registration_open,created_by) VALUES(?,?,?,?,?,?,?,?,1,?)',[!empty($d['department_id'])?App::id($d['department_id']):null,App::text($d['title']??null,'Title',180),$d['description']?:null,$d['location']?:null,$d['start_at'],$d['end_at']?:null,max(1,(int)($d['instructor_seats']??1)),max(1,(int)($d['student_seats']??1)),$u['id']]);App::redirect('/training');}
  if(preg_match('~^/training/admin/(\d+)/toggle$~',$path,$m)){App::query('UPDATE training_sessions SET registration_open=NOT registration_open WHERE id=?',[(int)$m[1]]);App::redirect('/training');}
  if(preg_match('~^/training/admin/(\d+)/rules$~',$path,$m)){$cert=!empty($d['certification_id'])?App::id($d['certification_id']):null;$stage=in_array($d['advance_recruit_stage']??null,['accepted','recruit','training','evaluation','member','failed','removed'],true)?$d['advance_recruit_stage']:null;$minimum=isset($d['minimum_score'])&&$d['minimum_score']!==''?(float)$d['minimum_score']:null;if(($minimum!==null&&($minimum<0||$minimum>100))||(!$cert&&!$stage&&empty($d['complete_probation'])))throw new HttpError('Choose a progression action and a valid minimum score.');App::query('INSERT INTO training_certification_rules(training_id,certification_id,minimum_score,advance_recruit_stage,complete_probation,notify_member,is_enabled,created_by) VALUES(?,?,?,?,?,?,1,?)',[(int)$m[1],$cert,$minimum,$stage,(int)!empty($d['complete_probation']),(int)!empty($d['notify_member']),$u['id']]);App::redirect('/training');}
  if(preg_match('~^/training/admin/(\d+)/registrations/(\d+)/complete$~',$path,$m)){Training::complete($u,(int)$m[1],(int)$m[2],$d);App::redirect('/training');}
  throw new HttpError('Training action not found.',404);
 }if($path!=='/training')throw new HttpError('Page not found.',404);View::layout('Training sessions',function()use($u){View::heading('Training sessions');foreach(App::rows('SELECT t.*,d.name department_name FROM training_sessions t LEFT JOIN departments d ON d.id=t.department_id ORDER BY t.start_at DESC LIMIT 100') as $t){?><section class="panel"><h2><?=escape($t['title'])?></h2><p><?=escape($t['start_at'].' · '.$t['location'])?></p><?php View::prose($t['description']);if($t['registration_open'])View::form('/training/'.$t['id'].'/register',['registration_type'=>['label'=>'Register as','options'=>['student'=>'Student',...(in_array($u['role'],[...self::HEADS,'staff'],true)?['instructor'=>'Instructor']:[])]]],'Register');View::form('/training/'.$t['id'].'/cancel',[],'Cancel my registration');$roster=App::rows('SELECT r.*,u.display_name FROM training_registrations r JOIN users u ON u.id=r.user_id WHERE r.training_id=? ORDER BY r.registration_type DESC,u.display_name',[$t['id']]);View::table($roster,['display_name'=>'Member','registration_type'=>'Type','status'=>'Attendance','result_status'=>'Result','score'=>'Score'],in_array($u['role'],self::HEADS,true)?function($r)use($t){View::form('/training/admin/'.$t['id'].'/registrations/'.$r['id'].'/complete',['result_status'=>['label'=>'Result','options'=>['passed'=>'Passed','failed'=>'Failed','incomplete'=>'Incomplete']],'score'=>['label'=>'Score %','type'=>'number'],'instructor_notes'=>['label'=>'Instructor notes','type'=>'textarea']],'Record completion',$r);}:null);if(in_array($u['role'],self::HEADS,true)){View::form('/training/admin/'.$t['id'].'/toggle',[],'Toggle registration');View::form('/training/admin/'.$t['id'].'/rules',['certification_id'=>['label'=>'Certification','options'=>([''=>'None']+array_column(App::rows('SELECT id,name FROM certifications ORDER BY name'),'name','id'))],'minimum_score'=>['label'=>'Minimum score %','type'=>'number'],'advance_recruit_stage'=>['label'=>'Recruit stage','options'=>array_combine(['','accepted','recruit','training','evaluation','member','failed','removed'],['No change','Accepted','Recruit','Training','Evaluation','Member','Failed','Removed'])],'complete_probation'=>['label'=>'Complete probation','type'=>'checkbox'],'notify_member'=>['label'=>'Notify member','type'=>'checkbox','default'=>true]],'Add certification/progression rule');}?></section><?php }if(in_array($u['role'],self::HEADS,true))View::form('/training/admin/create',['title'=>['label'=>'Title','required'=>true],'department_id'=>['label'=>'Department ID','type'=>'number'],'start_at'=>['label'=>'Start','type'=>'datetime-local','required'=>true],'end_at'=>['label'=>'End','type'=>'datetime-local'],'location'=>'Location','description'=>['label'=>'Description','type'=>'textarea'],'instructor_seats'=>['label'=>'Instructor seats','type'=>'number','default'=>1],'student_seats'=>['label'=>'Student seats','type'=>'number','default'=>10]],'Create training session');});}
}
